SELECT COUNT(*) FROM equipment e
LEFT JOIN processing p ON e.equipregistry = p.equipref
LEFT JOIN mesh m ON e.equipregistry = m.equipref;

-- Check how many distinct equiprefs across processing and mesh combined
SELECT COUNT(DISTINCT p.equipref) as proc_count, COUNT(DISTINCT m.equipref) as mesh_count
FROM processing p, mesh m;

-- Try UNION of processing and mesh equiprefs
SELECT COUNT(*) FROM (
    SELECT DISTINCT equipref FROM processing 
    UNION 
    SELECT DISTINCT equipref FROM mesh
) t;

-- Maybe it's just equipment with processing records, no mesh join needed
SELECT COUNT(DISTINCT e.equipregistry) FROM equipment e
JOIN processing p ON e.equipregistry = p.equipref;

-- Maybe equipment LEFT JOIN processing (so all equipment, even without processing)
SELECT COUNT(*) FROM equipment e
LEFT JOIN processing p ON e.equipregistry = p.equipref;

